const http = require('http');
const WebSocket = require('ws');
const { Pool } = require('pg');

const pool = new Pool();
const server = http.createServer();
const wss = new WebSocket.Server({ server });

const channelSockets = new Map();

wss.on('connection', (ws, req) => {
  ws.username = req.headers['x-auth-user'];
  if (!ws.username) {
    ws.close();
    return;
  }

  ws.on('message', async (msg) => {
    const { event, channelId } = JSON.parse(msg);

    if (event === 'TYPING') {
      // Verify channel membership before joining room
      const member = await pool.query(
        'SELECT 1 FROM channel_participants WHERE channel_id = $1 AND username = $2',
        [channelId, ws.username]
      );

      if (member.rowCount === 0) {
        ws.send(JSON.stringify({ error: 'Not a member of this channel' }));
        return;
      }

      if (!channelSockets.has(channelId)) {
        channelSockets.set(channelId, new Set());
      }
      channelSockets.get(channelId).add(ws);

      for (const client of channelSockets.get(channelId)) {
        if (client !== ws && client.readyState === WebSocket.OPEN) {
          client.send(JSON.stringify({ event: 'USER_TYPING', user: ws.username, channelId }));
        }
      }
    }
  });
});

server.listen(8005);
